// Идемпотентность через уникальный ключ обработки (PostgreSQL)
// таблица: processed_events(event_id uuid primary key, consumer text, processed_at)
async function handleIdempotent(eventId: string, consumer: string, work: () => Promise<void>) {
  await db.transaction(async (tx) => {
    const inserted = await tx.oneOrNone(
      `INSERT INTO processed_events (event_id, consumer, processed_at)
       VALUES ($1, $2, now()) ON CONFLICT DO NOTHING RETURNING event_id`,
      [eventId, consumer],
    );
    if (!inserted) return;   // уже обработано -> тихо выходим (дубль от Kafka)
    await work();            // бизнес-действие в той же транзакции -> "exactly-once" по эффекту
  });
}

import { Kafka, logLevel, EachMessagePayload } from 'kafkajs';

export const kafka = new Kafka({
  clientId: 'orders-svc',
  brokers: (process.env.KAFKA_BROKERS ?? 'localhost:9092').split(','),
  logLevel: logLevel.WARN,
  retry: { initialRetryTime: 300, retries: 8 },
  connectionTimeout: 10_000,
  requestTimeout: 30_000,
});

// ---- Продюсер: транзакционная запись события ----
const producer = kafka.producer({
  idempotent: true,                       // дедупликация при повторной отправке
  transactionTimeoutMs: 60_000,
});
await producer.connect();

export async function publishOrderEvent(evt: { id: string; orderId: string; type: string; payload: unknown }) {
  await producer.send({
    topic: 'order.events.v1',
    acks: -1,                             // ждём подтверждения ISR
    compression: CompressionTypes.GZIP,
    messages: [{
      key: evt.orderId,                   // порядок по конкретному заказу
      value: JSON.stringify(evt),         // тело
      headers: { 'event-id': evt.id, 'schema-version': '1', 'produced-at': String(Date.now()) },
      timestamp: String(Date.now()),
    }],
  });
}

// ---- Консьюмер: явные офсеты, ретраи, DLQ ----
const consumer = kafka.consumer({ groupId: 'notifications-svc', fromBeginning: false });
await consumer.subscribe({ topic: 'order.events.v1', fromBeginning: false });

await consumer.run({
  autoCommit: false,                      // коммит ТОЛЬКО после успешной обработки
  eachMessage: async ({ topic, partition, message }: EachMessagePayload) => {
    const eventId = message.headers?.['event-id']?.toString() ?? `${topic}:${partition}:${message.offset}`;
    try {
      const event = schema.parse(JSON.parse(message.value!.toString()));  // валидация схемой
      await handleIdempotent(eventId, 'notifications', () => notify(event));
      await consumer.commitOffsets([{ topic, partition, offset: (BigInt(message.offset) + 1n).toString() }]);
    } catch (err) {
      const attempts = Number(message.headers?.['x-attempts'] ?? 0);
      if (attempts < 3) {
        await retryLater(message);        // delayed retry topic / Redis-очередь
      } else {
        await sendToDlq(topic, message, err);  // мёртвая очередь + алерт
        await consumer.commitOffsets([{ topic, partition, offset: (BigInt(message.offset) + 1n).toString() }]);
      }
    }
  },
});

// Контракт события — единый источник истины (packages/contracts)
import { z } from 'zod';

export const OrderPaidV1 = z.object({
  eventId: z.uuid(),                          // ключ идемпотентности
  eventType: z.literal('order.paid.v1'),
  occurredAt: z.iso.datetime(),
  correlationId: z.uuid(),
  aggregate: z.object({ id: z.uuid(), version: z.number().int().positive() }),
  payload: z.object({
    orderId: z.uuid(),
    customerId: z.uuid(),
    amountCents: z.int().positive(),
    currency: z.string().length(3),
  }),
});
export type OrderPaidV1 = z.infer<typeof OrderPaidV1>;

-- Transactional outbox: бизнес-данные и событие атомарно
BEGIN;
  UPDATE orders SET status = 'paid' WHERE id = $1 AND status = 'pending' RETURNING *;
  INSERT INTO outbox (id, aggregate_type, aggregate_id, event_type, payload, created_at)
  VALUES (gen_random_uuid(), 'order', $1, 'order.paid.v1', $2::jsonb, now());
COMMIT;

-- Релей (polling-вариант): публикуем и помечаем отправленным
SELECT * FROM outbox WHERE published_at IS NULL ORDER BY created_at LIMIT 100;
-- после успешной отправки: UPDATE outbox SET published_at = now() WHERE id = ANY($1);
-- при ошибке: остаётся неопубликованным -> следующий цикл повторит (at-least-once + идемпотентный продюсер)

// Рабочая схема консьюмера в Nest: каждый топик = отдельный модуль с сервисом-хендлером
@Injectable()
export class OrderEventsConsumer implements OnModuleInit, OnModuleDestroy {
  private readonly consumer = this.kafka.consumer({ groupId: 'billing-svc' });

  constructor(
    private readonly kafka: KafkaService,
    private readonly billing: BillingService,
    private readonly processed: ProcessedEventsRepo,
    private readonly dlq: DlqService,
  ) {}

  async onModuleInit() {
    await this.consumer.connect();
    await this.consumer.subscribe({ topic: 'order.events.v1', fromBeginning: false });
    await this.consumer.run({
      autoCommit: false,
      eachMessage: (payload) => this.handle(payload),   // последовательно внутри партиции
    });
  }

  private async handle({ topic, partition, message }: EachMessagePayload) {
    const raw = JSON.parse(message.value!.toString());
    const eventId = raw.eventId ?? `${topic}:${partition}:${message.offset}`;
    try {
      const event = OrderPaidV1.parse(raw);
      await this.processed.runOnce(eventId, 'billing', () => this.billing.apply(event));
      await commit(this.consumer, topic, partition, message.offset);
    } catch (err) {
      await this.dlq.send({ topic, partition, message, error: String(err), at: new Date() });
      await commit(this.consumer, topic, partition, message.offset); // не блокируем партицию
      this.logger.error({ eventId, err }, 'event moved to DLQ');
    }
  }

  async onModuleDestroy() { await this.consumer.disconnect(); }
}
